export function navigationBackLabel(target,action){return action==='closeQuick'?'← 하던 장면으로':`← ${screenNames[target]??'이전 화면'}`;}
export function forecastDays(day){return Array.from({length:Math.max(0,Math.min(4,15-day))},(_,i)=>day+i);}
